-- V55: Platform clinical catalogs (symptoms, dosage templates, ICD).
-- Hospitals do not maintain these; doctors consume them as dropdowns.
-- hospital_id NULL = platform-wide default, visible to every hospital.

ALTER TABLE hospital.symptom_catalog
    ALTER COLUMN hospital_id DROP NOT NULL;

ALTER TABLE hospital.dosage_templates
    ALTER COLUMN hospital_id DROP NOT NULL;

ALTER TABLE hospital.diagnosis_catalog
    ALTER COLUMN hospital_id DROP NOT NULL;

DROP INDEX IF EXISTS hospital.uq_symptom_catalog_hospital_code;
CREATE UNIQUE INDEX IF NOT EXISTS uq_symptom_catalog_scope_code
    ON hospital.symptom_catalog (
        COALESCE(hospital_id, '00000000-0000-0000-0000-000000000000'),
        COALESCE(branch_id, '00000000-0000-0000-0000-000000000000'),
        lower(code)
    )
    WHERE deleted_at IS NULL AND code IS NOT NULL;

DROP INDEX IF EXISTS hospital.uq_diagnosis_catalog_hospital_code;
CREATE UNIQUE INDEX IF NOT EXISTS uq_diagnosis_catalog_scope_code
    ON hospital.diagnosis_catalog (
        COALESCE(hospital_id, '00000000-0000-0000-0000-000000000000'),
        COALESCE(branch_id, '00000000-0000-0000-0000-000000000000'),
        lower(icd_code)
    )
    WHERE deleted_at IS NULL;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;
